// ==UserScript==
// @name         Ricochet SDR Transfer Script Sync
// @namespace    local.ricochet-sdr-transfer-script-sync
// @version      2.3.4
// @description  Sync the current Ricochet lead into the supplied home/auto SDR transfer guide.
// @author       JKira & Mr.G
// @homepageURL  https://github.com/ugomez809/GIA-TamperMonkey/tree/main/Ricochet/Call%20Script
// @updateURL    https://raw.githubusercontent.com/ugomez809/GIA-TamperMonkey/main/Ricochet/Call%20Script/ricochet-sdr-sync.user.js
// @downloadURL  https://raw.githubusercontent.com/ugomez809/GIA-TamperMonkey/main/Ricochet/Call%20Script/ricochet-sdr-sync.user.js
// @match        https://giainc.ricochet.me/*
// @match        https://example.com/*
// @run-at       document-idle
// @noframes
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_addValueChangeListener
// @grant        GM_registerMenuCommand
// @grant        unsafeWindow
// ==/UserScript==

(function () {
'use strict';
const TEMPLATE_HTML = "<!doctype html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<script>\ntry { document.documentElement.dataset.theme = localStorage.getItem('sdr-script-theme-v1') === 'dark' ? 'dark' : 'light'; } catch (_) {}\n</script>\n<style>html,body{margin:0}img{max-width:100%}[hidden]{display:none!important}</style>\n</head>\n<body>\n<title>SDR Transfer Script</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=Source+Serif+4:opsz,wght@8..60,400;8..60,600&display=swap\">\n<style>\n:root{\n  --paper:#F4F6F4;\n  --surface:#FFFFFF;\n  --surface-2:#EDF1EF;\n  --ink:#12201C;\n  --ink-2:#4E615A;\n  --ink-3:#7C8E87;\n  --line:#D7E0DB;\n  --line-strong:#B8C6C0;\n  --accent:#0B6B5B;\n  --accent-ink:#075247;\n  --accent-soft:#E2EFEB;\n  --signal:#9A5D06;\n  --signal-soft:#FAEFDC;\n  --signal-line:#E2C489;\n  --focus:#0B6B5B;\n  --sans:\"IBM Plex Sans\",ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --serif:\"Source Serif 4\",Georgia,\"Times New Roman\",serif;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --paper:#0D1412;\n    --surface:#151F1C;\n    --surface-2:#1C2926;\n    --ink:#E7EFEB;\n    --ink-2:#A3B5AE;\n    --ink-3:#7F918B;\n    --line:#2A3833;\n    --line-strong:#3C4E48;\n    --accent:#4FC9AF;\n    --accent-ink:#8FE0CD;\n    --accent-soft:#11302A;\n    --signal:#E5AF57;\n    --signal-soft:#2C2314;\n    --signal-line:#5A4620;\n    --focus:#4FC9AF;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --paper:#0D1412;\n  --surface:#151F1C;\n  --surface-2:#1C2926;\n  --ink:#E7EFEB;\n  --ink-2:#A3B5AE;\n  --ink-3:#7F918B;\n  --line:#2A3833;\n  --line-strong:#3C4E48;\n  --accent:#4FC9AF;\n  --accent-ink:#8FE0CD;\n  --accent-soft:#11302A;\n  --signal:#E5AF57;\n  --signal-soft:#2C2314;\n  --signal-line:#5A4620;\n  --focus:#4FC9AF;\n}\n\n*{box-sizing:border-box}\nbody{\n  background:var(--paper);\n  color:var(--ink);\n  font-family:var(--sans);\n  font-size:15px;\n  line-height:1.5;\n  margin:0;\n}\n.wrap{max-width:1200px;margin:0 auto;padding-left:16px;padding-right:16px;padding-block:0 40px}\n/* Keep the script full width in split view; objections open on demand. */\n.shell{\n  display:grid;\n  grid-template-columns:minmax(0,1fr) clamp(230px, 34%, 352px);\n  gap:clamp(10px, 2vw, 22px);\n  align-items:start;\n}\nmain{min-width:0}\n@media (max-width:1200px){\n  .shell{display:block}\n}\n/* autofilled by userscript: collapse the input rows, keep the script */\nbody.fields-hidden .bar .fields{display:none}\n\n/* ---------- sticky control bar ---------- */\n.bar{\n  position:sticky;\n  top:env(safe-area-inset-top, 0px);\n  z-index:20;\n  background:var(--surface);\n  border-bottom:1px solid var(--line);\n  padding:8px 16px;\n}\n.bar-inner{max-width:1200px;margin:0 auto;display:flex;flex-direction:column;gap:9px}\n/* one row: who is calling, which script, which line, then actions. Wraps as a unit when narrow. */\n.bar-row{display:flex;align-items:center;gap:8px 12px;flex-wrap:wrap;--ctl:32px}\n.bar-row .tabs{margin:0}\n.bar-actions{margin-left:auto;display:flex;gap:6px;flex-wrap:wrap}\n.bar-row .btn{height:var(--ctl);padding:0 12px;display:inline-flex;align-items:center}\n\nbutton{font-family:inherit;font-size:12.5px;font-weight:600;cursor:pointer}\n.btn{\n  border:1px solid var(--line-strong);\n  background:var(--surface-2);\n  color:var(--ink);\n  border-radius:6px;\n  padding:6px 10px;\n  white-space:nowrap;\n  transition:background .12s ease,border-color .12s ease;\n}\n.btn:hover{border-color:var(--accent);color:var(--accent-ink)}\n.btn[aria-expanded=\"true\"]{border-color:var(--accent);color:var(--accent-ink)}\n.btn-primary{background:var(--accent);border-color:var(--accent);color:var(--surface)}\n.btn-primary:hover{filter:brightness(1.08)}\n\n/* ---------- field grids ---------- */\n.fields{display:grid;grid-template-columns:repeat(12,1fr);gap:8px 10px}\n.fields > .field{grid-column:span 3}\n.fields > .field.field-sm{grid-column:span 2}\n@media (max-width:900px){.fields > .field,.fields > .field.field-sm{grid-column:span 4}}\n@media (max-width:560px){.fields > .field,.fields > .field.field-sm{grid-column:span 6}}\n.field{display:flex;flex-direction:column;gap:3px;min-width:0}\n.field label{\n  font-size:10.5px;font-weight:600;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3);\n}\ninput[type=text],select{\n  font-family:inherit;font-size:14px;color:var(--ink);\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:5px;\n  padding:7px 9px;\n  width:100%;min-width:0;\n}\ninput[type=text]:focus-visible,select:focus-visible,button:focus-visible{\n  outline:2px solid var(--focus);outline-offset:1px;\n}\ninput::placeholder{color:var(--ink-3);opacity:.7}\n\n.sdrfield,.swgroup,.agency{display:flex;align-items:center;gap:8px}\n.agency-name{font-size:13.5px;font-weight:600;color:var(--ink);white-space:nowrap;max-width:120px;overflow:hidden;text-overflow:ellipsis}\n.btn-icon{width:var(--ctl);padding:0;justify-content:center;font-size:15px;line-height:1}\n.sdrfield label,.swlab{\n  font-size:10.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-3);\n}\n.sdrfield input{width:120px;height:var(--ctl);padding:0 10px;font-size:13.5px}\n.lead-switch,.lob-switch{\n  margin:0;gap:0;height:var(--ctl);padding:2px;box-sizing:border-box;\n  border:1px solid var(--line-strong);border-radius:20px;background:var(--surface-2);\n  display:inline-flex;align-items:stretch;\n}\n.lead-switch .tab,.lob-switch .tab{\n  border:none;background:transparent;padding:0 11px;font-size:12.5px;line-height:1;\n  display:inline-flex;align-items:center;\n}\n.lob-switch .tab[aria-selected=\"true\"]{background:var(--accent)}\nbody[data-mode=\"old\"] .lob-switch .tab[aria-selected=\"true\"]{background:var(--signal)}\n\n/* ---------- script mode ---------- */\n.modebar{\n  display:flex;align-items:center;gap:10px;flex-wrap:wrap;\n  margin-top:14px;padding:9px 14px;\n  border-radius:8px;\n  border:1px solid var(--accent);\n  background:var(--accent-soft);\n  color:var(--accent-ink);\n  font-size:12px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;\n}\n.modebar .what{\n  font-weight:500;letter-spacing:.02em;text-transform:none;font-size:12.5px;\n  color:var(--ink-2);\n}\nbody[data-mode=\"old\"] .modebar{\n  border-color:var(--signal-line);\n  background:var(--signal-soft);\n  color:var(--signal);\n}\nbody[data-mode=\"old\"] .num{background:var(--signal)}\n.lead-switch .tab[aria-selected=\"true\"]{background:var(--accent)}\nbody[data-mode=\"old\"] .lead-switch .tab[aria-selected=\"true\"]{background:var(--signal)}\n\n/* ---------- steps ---------- */\n.step{\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:8px;\n  margin-top:14px;\n  overflow:hidden;\n}\n.step-head{\n  display:flex;align-items:center;gap:10px;\n  padding:11px 16px;\n  border-bottom:1px solid var(--line);\n  background:var(--surface-2);\n}\n.num{\n  flex:none;\n  width:22px;height:22px;border-radius:50%;\n  display:grid;place-items:center;\n  background:var(--accent);color:var(--surface);\n  font-size:11px;font-weight:700;\n  font-variant-numeric:tabular-nums;\n}\n.step-head h2{margin:0;font-size:13px;font-weight:600;letter-spacing:.04em;text-transform:uppercase}\n.step-head .hint{margin-left:auto;font-size:11.5px;color:var(--ink-3);font-weight:500}\n.step-body{padding:14px 16px}\n\n/* spoken lines */\n.say{\n  font-family:var(--serif);\n  font-size:18px;\n  line-height:1.55;\n  margin:0;\n  color:var(--ink);\n}\n.say + .say{margin-top:11px}\n.say-group > .say + .say{margin-top:0}\n.say-group{display:flex;flex-direction:column;gap:11px}\n\n.tok{\n  font-family:var(--sans);\n  font-size:.86em;\n  font-weight:600;\n  color:var(--accent-ink);\n  background:var(--accent-soft);\n  border-radius:4px;\n  padding:1px 4px;\n  margin:0 -1px;\n  white-space:nowrap;\n}\n.tok.empty{\n  color:var(--signal);\n  background:var(--signal-soft);\n  box-shadow:inset 0 -1px 0 var(--signal-line);\n  font-weight:500;\n  font-style:italic;\n}\n\n/* action / instruction chips */\n.action{\n  display:flex;align-items:center;gap:8px;\n  background:var(--signal-soft);\n  border:1px solid var(--signal-line);\n  border-radius:6px;\n  padding:9px 12px;\n  font-size:12.5px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;\n  color:var(--signal);\n}\n.action::before{content:\"\";flex:none;width:7px;height:7px;border-radius:50%;background:var(--signal)}\nbutton.action{\n  width:100%;text-align:left;cursor:pointer;font-family:inherit;\n  transition:background .12s ease,border-color .12s ease;\n  animation:notify-pulse 2.6s ease-in-out infinite;\n}\n@keyframes notify-pulse{\n  0%,100%{transform:scale(1);box-shadow:0 0 0 0 color-mix(in srgb, var(--signal) 45%, transparent)}\n  50%{transform:scale(1.015);box-shadow:0 0 0 7px color-mix(in srgb, var(--signal) 0%, transparent)}\n}\n.notify-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.notify-row button.action{flex:1 1 270px;width:auto;margin:0}\n.quote-action{flex:0 0 auto;font:11px system-ui;padding:5px 7px;border:1px solid var(--line-strong);border-radius:5px;background:var(--surface);color:var(--ink);cursor:pointer}\n.action-status{font:12px system-ui;color:var(--ink-2);margin:6px 0 0}\nbutton[data-action]:disabled{cursor:default;opacity:.65;animation:none}\nbutton.action.done{animation:none}\nbutton.action:hover{border-color:var(--signal);filter:brightness(.97)}\nbutton.action.fired{background:var(--accent-soft);border-color:var(--accent);color:var(--accent-ink)}\nbutton.action.fired::before{background:var(--accent)}\n.note{\n  font-size:13px;color:var(--ink-2);\n  border-left:2px solid var(--line-strong);\n  padding-left:11px;\n}\n\n/* branch tabs */\n.tabs{display:flex;gap:6px;margin-bottom:13px;flex-wrap:wrap}\n.tab{\n  border:1px solid var(--line-strong);\n  background:transparent;\n  color:var(--ink-2);\n  border-radius:20px;\n  padding:6px 14px;\n  font-size:12.5px;\n}\n.tab[aria-selected=\"true\"]{background:var(--accent);border-color:var(--accent);color:var(--surface)}\n.sub-tabs{margin-top:13px;margin-bottom:0}\n\n/* discovery */\n.cond{\n  background:var(--signal-soft);\n  border:1px solid var(--signal-line);\n  border-radius:6px;\n  padding:10px 13px;\n  margin-bottom:14px;\n  font-size:13.5px;\n  color:var(--signal);\n  font-weight:500;\n}\n.cond strong{font-weight:700}\n.step-body{counter-reset:q}\n.q{display:grid;grid-template-columns:20px 1fr;gap:4px 10px;padding:13px 0;border-top:1px solid var(--line)}\n.say + .q{border-top:none;padding-top:2px}\n.q{counter-increment:q}\n.q.extra{counter-increment:none}\n.q-n{\n  font-size:12px;font-weight:700;color:var(--ink-3);\n  font-variant-numeric:tabular-nums;padding-top:5px;\n}\n.q:not(.extra) .q-n::before{content:counter(q)}\n.q-text{font-family:var(--serif);font-size:17px;line-height:1.5}\n.q-in{grid-column:2}\n.q-in input{margin-top:2px}\n.q.statement .q-text{color:var(--ink-2)}\n\n.toast{\n  position:fixed;left:50%;bottom:22px;transform:translateX(-50%) translateY(8px);\n  background:var(--accent);color:var(--surface);\n  padding:9px 16px;border-radius:6px;font-size:13px;font-weight:600;\n  opacity:0;pointer-events:none;transition:opacity .18s ease,transform .18s ease;\n  z-index:50;\n}\n.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}\n/* ---------- objections: rail on desktop, drawer when narrow ---------- */\n.scrim{display:none}\n#btnObj{display:none}\n.drawer{\n  position:sticky;\n  top:calc(var(--barh, 150px) + 14px);\n  max-height:calc(100vh - var(--barh, 150px) - 28px);\n  margin-top:14px;\n  background:var(--surface);\n  border:1px solid var(--line);\n  border-radius:8px;\n  display:flex;flex-direction:column;\n  overflow:hidden;\n}\n.drawer-close{display:none}\n.drawer-head{\n  padding:12px 14px;\n  border-bottom:1px solid var(--line);\n  background:var(--surface-2);\n  display:flex;flex-direction:column;gap:9px;\n}\n.drawer-title{display:flex;align-items:center;gap:10px}\n.drawer-title h2{margin:0;font-size:13px;font-weight:700;letter-spacing:.05em;text-transform:uppercase}\n.drawer-title .count{font-size:11px;color:var(--ink-3);font-variant-numeric:tabular-nums}\n.drawer-close:hover{background:var(--paper);color:var(--ink)}\n.drawer-body{flex:1;overflow-y:auto;padding:2px 14px 14px}\n\n.obj{border-bottom:1px solid var(--line)}\n.obj > summary{\n  cursor:pointer;list-style:none;\n  display:grid;grid-template-columns:20px 1fr;gap:10px;align-items:start;\n  padding:11px 0;\n  font-family:var(--serif);font-size:16px;line-height:1.35;\n}\n.obj > summary::-webkit-details-marker{display:none}\n.obj > summary:hover{color:var(--accent-ink)}\n.obj > summary .on{\n  font-family:var(--sans);font-size:11.5px;font-weight:700;color:var(--ink-3);\n  font-variant-numeric:tabular-nums;padding-top:3px;\n}\n.obj[open] > summary{color:var(--accent-ink);font-weight:600}\n.obj-body{padding:0 0 14px 30px;display:flex;flex-direction:column;gap:9px}\n.obj-body .say{font-size:16px;line-height:1.5}\n.ack{\n  display:inline-block;font-family:var(--sans);\n  font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;\n  color:var(--accent);background:var(--accent-soft);\n  border-radius:3px;padding:2px 6px;margin-right:6px;vertical-align:1px;\n}\n.back{\n  font-family:var(--sans);font-size:11px;font-weight:600;\n  letter-spacing:.05em;text-transform:uppercase;color:var(--signal);\n  background:var(--signal-soft);border:1px solid var(--signal-line);\n  border-radius:4px;padding:6px 9px;\n}\n.pick{\n  font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.08em;\n  text-transform:uppercase;color:var(--ink-3);\n}\n.alt{border-left:2px solid var(--line-strong);padding-left:11px;display:flex;flex-direction:column;gap:8px}\n.coach{\n  font-family:var(--sans);font-size:.8em;font-weight:500;font-style:italic;\n  color:var(--ink-3);white-space:nowrap;\n}\n.nores{padding:24px 0;text-align:center;color:var(--ink-3);font-size:13px}\n\n/* tighten the rail as the window narrows, so it still fits at half-screen */\n@media (max-width:1100px){\n  .obj > summary{font-size:15px;gap:8px;padding:10px 0}\n  .obj-body{padding-left:0}\n  .obj-body .say{font-size:15px}\n  .say{font-size:17px}\n  .drawer-head{padding:10px 12px;gap:8px}\n  .drawer-body{padding:2px 12px 12px}\n}\n@media (max-width:860px){\n  .obj > summary{font-size:14.5px}\n  .obj-body .say{font-size:14.5px;line-height:1.45}\n  .say{font-size:16px}\n  .step-body{padding:12px 13px}\n  .step-head{padding:10px 13px}\n  .back{font-size:10px;padding:5px 7px}\n}\n\n@media (max-width:700px){\n  .obj > summary{font-size:14px;padding:9px 0}\n  .obj-body .say{font-size:14px}\n  .say{font-size:15.5px}\n  .drawer-head{padding:9px 10px}\n  .drawer-body{padding:2px 10px 10px}\n  .ack{font-size:9px;padding:1px 4px}\n}\n\n/* Split view: objections move into a drawer behind the toolbar button. */\n@media (max-width:1200px){\n  #btnObj{display:inline-block}\n  .scrim{\n    display:block;\n    position:fixed;inset:0;background:rgba(8,20,17,.45);\n    opacity:0;pointer-events:none;transition:opacity .16s ease;z-index:30;\n  }\n  .scrim.open{opacity:1;pointer-events:auto}\n  .drawer{\n    position:fixed;top:0;right:0;bottom:0;left:auto;\n    width:min(440px,100%);max-height:none;margin-top:0;\n    border:none;border-left:1px solid var(--line);border-radius:0;\n    transform:translateX(100%);\n    transition:transform .18s ease;\n    z-index:31;\n  }\n  .drawer.open{transform:translateX(0)}\n  .drawer-head{\n    padding:12px 16px;\n    padding-top:calc(12px + env(safe-area-inset-top, 0px));\n  }\n  .drawer-close{\n    display:block;\n    margin-left:auto;border:none;background:transparent;color:var(--ink-2);\n    font-size:20px;line-height:1;padding:2px 6px;border-radius:4px;\n  }\n  .drawer-body{\n    padding:4px 16px 16px;\n    padding-bottom:calc(16px + env(safe-area-inset-bottom, 0px));\n  }\n}\n\n/* phone, single column: the drawer has room again, type goes back up */\n@media (max-width:480px){\n  .say{font-size:16.5px}\n  .q-text{font-size:16px}\n  .obj > summary{font-size:15px}\n  .obj-body .say{font-size:15px}\n  .bar-actions{width:100%;margin-left:0}\n}\n@media (prefers-reduced-motion: reduce){*{transition:none!important;animation:none!important}}\n</style>\n\n<div class=\"bar\">\n  <div class=\"bar-inner\">\n    <div class=\"bar-row\">\n      <div class=\"sdrfield\">\n        <label for=\"f_sdrName\">SDR</label>\n        <input type=\"text\" id=\"f_sdrName\" data-fill=\"sdrName\" placeholder=\"Your name\" autocomplete=\"off\">\n      </div>\n      <div class=\"swgroup\">\n        <span class=\"swlab\">Lead</span>\n        <div class=\"tabs lead-switch\" role=\"tablist\" aria-label=\"Which script\">\n          <button class=\"tab\" role=\"tab\" type=\"button\" data-lead=\"new\" aria-selected=\"true\">New</button>\n          <button class=\"tab\" role=\"tab\" type=\"button\" data-lead=\"old\" aria-selected=\"false\">Old</button>\n        </div>\n      </div>\n      <div class=\"swgroup\">\n        <span class=\"swlab\">Line</span>\n        <div class=\"tabs lob-switch\" role=\"tablist\" aria-label=\"Line of business\">\n          <button class=\"tab\" role=\"tab\" type=\"button\" data-lob=\"home\" aria-selected=\"true\">Home</button>\n          <button class=\"tab\" role=\"tab\" type=\"button\" data-lob=\"auto\" aria-selected=\"false\">Auto</button>\n        </div>\n      </div>\n      <div class=\"agency\">\n        <span class=\"swlab\">Agency</span>\n        <span class=\"agency-name\" id=\"agencyName\" data-fill=\"agency\">&mdash;</span>\n      </div>\n      <div class=\"bar-actions\">\n        <button class=\"btn\" id=\"btnFields\" type=\"button\" aria-expanded=\"true\">Fields</button>\n        <button class=\"btn\" id=\"btnObj\" type=\"button\" aria-expanded=\"false\">Objections</button>\n        <button class=\"btn\" id=\"btnReset\" type=\"button\">Reset</button>\n        <button class=\"btn btn-primary\" id=\"btnCopy\" type=\"button\">Copy note</button>\n      </div>\n    </div>\n\n    <div class=\"fields\">\n      <div class=\"field\">\n        <label for=\"f_prospect\">Prospect name</label>\n        <input type=\"text\" id=\"f_prospect\" data-fill=\"prospect\" placeholder=\"First name\" autocomplete=\"off\">\n      </div>\n      <div class=\"field\">\n        <label for=\"f_dob\">Date of birth</label>\n        <input type=\"text\" id=\"f_dob\" data-fill=\"dob\" placeholder=\"MM/DD/YYYY\" autocomplete=\"off\">\n      </div>\n      <div class=\"field\">\n        <label for=\"f_email\">Email on file</label>\n        <input type=\"text\" id=\"f_email\" data-fill=\"email\" placeholder=\"name@email.com\" autocomplete=\"off\">\n      </div>\n      <div class=\"field\">\n        <label for=\"f_spouse\">Spouse name</label>\n        <input type=\"text\" id=\"f_spouse\" data-fill=\"spouse\" placeholder=\"If it comes up\" autocomplete=\"off\">\n      </div>\n      <div class=\"field\">\n        <label for=\"f_vehicles\">Vehicles on file</label>\n        <input type=\"text\" id=\"f_vehicles\" data-fill=\"vehicles\" placeholder=\"2019 Honda Civic\" autocomplete=\"off\">\n      </div>\n      <div class=\"field\">\n        <label for=\"f_street\">Street address</label>\n        <input type=\"text\" id=\"f_street\" data-fill=\"street\" placeholder=\"123 Main St\" autocomplete=\"off\">\n      </div>\n      <div class=\"field field-sm\">\n        <label for=\"f_city\">City</label>\n        <input type=\"text\" id=\"f_city\" data-fill=\"city\" placeholder=\"Salinas\" autocomplete=\"off\">\n      </div>\n      <div class=\"field field-sm\">\n        <label for=\"f_state\">State</label>\n        <input type=\"text\" id=\"f_state\" data-fill=\"state\" placeholder=\"CA\" autocomplete=\"off\">\n      </div>\n      <div class=\"field field-sm\">\n        <label for=\"f_zip\">Zip</label>\n        <input type=\"text\" id=\"f_zip\" data-fill=\"zip\" placeholder=\"93901\" autocomplete=\"off\">\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class=\"wrap\">\n<div class=\"shell\">\n<main>\n\n  <div class=\"modebar\" id=\"modebar\">\n    <span id=\"modeName\">New internet lead</span>\n    <span class=\"what\" id=\"modeWhat\">They asked for a quote. Confirm details, stall, transfer.</span>\n  </div>\n\n  <div data-script=\"new\">\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">1</div>\n      <h2>Confirm you have the right person</h2>\n    </div>\n    <div class=\"step-body say-group\">\n      <p class=\"say\">Hello, is this <span class=\"tok\" data-tok=\"prospect\" data-ph=\"Prospect's Name\"></span>?</p>\n      <p class=\"say\">Hi <span class=\"tok\" data-tok=\"prospect\" data-ph=\"Prospect's Name\"></span>, this is <span class=\"tok\" data-tok=\"sdrName\" data-ph=\"Your Name\"></span> calling you from <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span>. How are you?</p>\n      <div class=\"notify-row\"><button type=\"button\" class=\"action done\" data-notify data-action=\"notify\" disabled>Notify sales agents the lead is on the line</button><button type=\"button\" class=\"quote-action\" data-action=\"quote\" disabled>Quoting / Info Form</button></div><div class=\"action-status\" role=\"status\" data-action-status></div>\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">2</div>\n      <h2>Confirm the details</h2>\n      <div class=\"hint\"><span class=\"tok\" data-tok=\"lobWord\" data-ph=\"Line\"></span></div>\n    </div>\n    <div class=\"step-body\">\n      <div class=\"say-group\" data-panel=\"auto\">\n        <p class=\"say\">I received your request for a car insurance quote, and we're working on that right now. Before we share the final price with you, I wanted to confirm a few details to get you the best price possible.</p>\n        <p class=\"say\">Looks like you have <span class=\"tok\" data-tok=\"vehicles\" data-ph=\"Make/Model of Vehicles\"></span>, do you have any other vehicles that you'd like for us to include in this quote?</p>\n        <p class=\"say\">Your complete address is <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Street / City / Zip Code\"></span>. Is that correct?</p>\n      </div>\n\n      <div class=\"say-group\" data-panel=\"home\" hidden>\n        <p class=\"say\">I see that you requested an insurance quote for your home on <span class=\"tok\" data-tok=\"street\" data-ph=\"Street Address\"></span>. Do you currently live in that home, or are you in the process of buying it?</p>\n\n        <div class=\"tabs sub-tabs\" role=\"tablist\" aria-label=\"Ownership status\">\n          <button class=\"tab\" role=\"tab\" type=\"button\" data-own=\"owns\" aria-selected=\"true\">Already owns it</button>\n          <button class=\"tab\" role=\"tab\" type=\"button\" data-own=\"buying\" aria-selected=\"false\">Buying the home</button>\n        </div>\n\n        <div data-own-panel=\"owns\">\n          <p class=\"say\">Perfect.</p>\n        </div>\n        <div data-own-panel=\"buying\" hidden>\n          <p class=\"say\">Congratulations! When do you close on the home? We'll work with your lender to make sure you close on time.</p>\n        </div>\n\n        <p class=\"say\">We have a quote started for you here and we'll share the final price with you in just a moment, but before we do that, I want to see if we can apply any discounts that the system may have missed.</p>\n        <p class=\"say\">To confirm, your home is in <span class=\"tok\" data-tok=\"cityStateZip\" data-ph=\"City, State, Zip Code\"></span>. Is that correct?</p>\n      </div>\n\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">3</div>\n      <h2>Confirm date of birth</h2>\n      <div class=\"hint\">Both lines of business</div>\n    </div>\n    <div class=\"step-body\">\n      <p class=\"say\">It looks like your date of birth is <span class=\"tok\" data-tok=\"dob\" data-ph=\"DOB\"></span>. Is that correct?</p>\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">4</div>\n      <h2>Stall questions</h2>\n      <div class=\"hint\">Capture the answers</div>\n    </div>\n    <div class=\"step-body\">\n      <div class=\"cond\"><strong>Only if the sales agent has not joined the call yet.</strong> Keep the prospect talking and collect what the agent will need.</div>\n      <p class=\"say\" style=\"margin-bottom:6px\">To make sure we give you the best price possible, I want to confirm:</p>\n\n      <div class=\"q\">\n        <div class=\"q-n\"></div>\n        <div class=\"q-text\">What company carries your insurance right now?</div>\n        <div class=\"q-in\" data-slot=\"carrier\"><input type=\"text\" id=\"d_carrier\" data-capture=\"carrier\" placeholder=\"Current carrier\" autocomplete=\"off\"></div>\n      </div>\n\n      <div class=\"q\">\n        <div class=\"q-n\"></div>\n        <div class=\"q-text\">I do want to ask, besides getting a better price, what made you shop for insurance today?</div>\n        <div class=\"q-in\" data-slot=\"reason\"><input type=\"text\" id=\"d_reason\" data-capture=\"reason\" placeholder=\"Reason for shopping\" autocomplete=\"off\"></div>\n      </div>\n\n      <div class=\"q statement\">\n        <div class=\"q-n\"></div>\n        <div class=\"q-text\">It's great that we connected today. Recently, we've been able to help a lot of people in <span class=\"tok\" data-tok=\"city\" data-ph=\"City\"></span> switch their insurance to <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span> because we have great rates, with better coverage. I'm glad that we are talking right now.</div>\n      </div>\n\n      <div class=\"q\">\n        <div class=\"q-n\"></div>\n        <div class=\"q-text\">We have discounts for certain occupations, what do you do for work?</div>\n        <div class=\"q-in\" data-slot=\"occupation\"><input type=\"text\" id=\"d_occupation\" data-capture=\"occupation\" placeholder=\"Occupation\" autocomplete=\"off\"></div>\n      </div>\n\n      <div class=\"q\" data-lob-alt=\"auto\">\n        <div class=\"q-n\"></div>\n        <div class=\"q-text\">About how many miles do you drive per year?</div>\n        <div class=\"q-in\" data-slot=\"miles\"><input type=\"text\" id=\"d_miles\" data-capture=\"miles\" placeholder=\"Miles per year\" autocomplete=\"off\" inputmode=\"numeric\"></div>\n      </div>\n\n      <div class=\"q\" data-lob-alt=\"home\">\n        <div class=\"q-n\"></div>\n        <div class=\"q-text\">What type of plumbing does the home have? Copper, galvanized, PVC, or PEX?</div>\n        <div class=\"q-in\" data-slot=\"plumbing\">\n          <select id=\"d_plumbing\" data-capture=\"plumbing\">\n            <option value=\"\">Plumbing type</option>\n            <option>Copper</option>\n            <option>Galvanized</option>\n            <option>PVC</option>\n            <option>PEX</option>\n            <option>Not sure</option>\n          </select>\n        </div>\n      </div>\n\n      <div class=\"q\" data-lob-alt=\"home\">\n        <div class=\"q-n\"></div>\n        <div class=\"q-text\">Do you run a business on your property?</div>\n        <div class=\"q-in\" data-slot=\"business\"><input type=\"text\" id=\"d_business\" data-capture=\"business\" placeholder=\"Yes / No / what kind\" autocomplete=\"off\"></div>\n      </div>\n\n      <div class=\"q extra\">\n        <div class=\"q-n\">+</div>\n        <div class=\"q-text\" style=\"font-family:var(--sans);font-size:13px;color:var(--ink-2)\">Anything else worth passing to the agent</div>\n        <div class=\"q-in\" data-slot=\"notes\"><input type=\"text\" id=\"d_notes\" data-capture=\"notes\" placeholder=\"Free notes\" autocomplete=\"off\"></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">5</div>\n      <h2>Hand off to the sales agent</h2>\n    </div>\n    <div class=\"step-body say-group\">\n      <p class=\"say\">I have <span class=\"coach\">[Sales Agent's Name]</span> on the line with us, who's working on your quote and will go over your discounts to make sure we're getting you the best price possible.</p>\n      <div class=\"note\">If the prospect gave you new information, share it with the sales agent. Hit <strong>Copy CRM note</strong> and paste it into the Teams channel conversation before you drop off.</div>\n    </div>\n  </section>\n\n  </div>\n\n  <div data-script=\"old\" hidden>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">1</div>\n      <h2>Introduction &amp; purpose of call</h2>\n    </div>\n    <div class=\"step-body say-group\">\n      <p class=\"say\"><span class=\"tok\" data-tok=\"greet\" data-ph=\"Good afternoon\"></span>, is this <span class=\"tok\" data-tok=\"prospect\" data-ph=\"Prospect's Name\"></span>?</p>\n      <p class=\"say\">Hey <span class=\"tok\" data-tok=\"prospect\" data-ph=\"Prospect's Name\"></span>, this is <span class=\"tok\" data-tok=\"sdrName\" data-ph=\"Your Name\"></span> calling you from <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span>. How are you?</p>\n      <p class=\"say\">I'm calling you because we gave you a <span class=\"tok\" data-tok=\"lobThing\" data-ph=\"Car/Home\"></span> insurance quote a while back, but we couldn't help you at that time. Since our rates have recently changed, I wanted to share our updated quote with you.</p>\n      <div class=\"notify-row\"><button type=\"button\" class=\"action done\" data-notify data-action=\"notify\" disabled>Notify sales agents the lead is on the line</button><button type=\"button\" class=\"quote-action\" data-action=\"quote\" disabled>Quoting / Info Form</button></div><div class=\"action-status\" role=\"status\" data-action-status></div>\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">2</div>\n      <h2><span data-lob-alt=\"auto\">Vehicle &amp; household information</span><span data-lob-alt=\"home\">Household information</span></h2>\n      <div class=\"hint\">Confirm before quoting</div>\n    </div>\n    <div class=\"step-body say-group\">\n      <div class=\"say-group\" data-lob-alt=\"auto\">\n        <p class=\"say\">Looks like you have <span class=\"tok\" data-tok=\"vehicles\" data-ph=\"Make/Model of Vehicles\"></span>, do you have any other vehicles that you'd like for us to include in this quote?</p>\n        <p class=\"say\">Are you still at <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Home Address\"></span>?</p>\n      </div>\n      <div class=\"say-group\" data-lob-alt=\"home\">\n        <p class=\"say\">Are you still at <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Home Address\"></span>?</p>\n        <div>\n          <div class=\"pick\">Select one</div>\n          <p class=\"say\" style=\"margin-top:5px\">You own that home, is that correct?</p>\n          <p class=\"say\">You rent that home, is that correct?</p>\n        </div>\n      </div>\n      <p class=\"say\">I see your date of birth is <span class=\"tok\" data-tok=\"dob\" data-ph=\"DOB\"></span>. Is that right?</p>\n      <p class=\"say\">Perfect. We have a quote started for you here and we'll share the final price with you in just a moment, but before we do that, I want to see if we can apply any discounts that the system may have missed.</p>\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">3</div>\n      <h2>Current carrier</h2>\n      <div class=\"hint\">Capture the answer</div>\n    </div>\n    <div class=\"step-body say-group\">\n      <div>\n        <div class=\"pick\">If you see their current carrier</div>\n        <p class=\"say\" style=\"margin-top:5px\">It looks like you're currently insured with <span class=\"tok\" data-tok=\"insurer\" data-ph=\"Current Insurer\"></span>. Is that right?</p>\n      </div>\n      <div>\n        <div class=\"pick\">If you don't see their current carrier</div>\n        <p class=\"say\" style=\"margin-top:5px\">Who are you currently insured with?</p>\n      </div>\n      <div data-slot=\"carrier\"></div>\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">4</div>\n      <h2>Benefit statement</h2>\n    </div>\n    <div class=\"step-body\">\n      <p class=\"say\">It's great that we connected today. Recently, we've been able to help a lot of people in <span class=\"tok\" data-tok=\"city\" data-ph=\"City\"></span> switch their insurance to <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span> because we have great rates, with better coverage. I'm glad that we are talking right now.</p>\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">5</div>\n      <h2><span data-lob-alt=\"auto\">Occupational discounts &amp; mileage</span><span data-lob-alt=\"home\">Occupational discounts &amp; plumbing</span></h2>\n      <div class=\"hint\">Capture the answers</div>\n    </div>\n    <div class=\"step-body say-group\">\n      <p class=\"say\">We do have discounts for certain occupations, what do you <span class=\"coach\">[and other named insureds]</span> do for work?</p>\n      <div data-slot=\"occupation\"></div>\n      <div class=\"say-group\" data-lob-alt=\"auto\">\n        <p class=\"say\">About how many miles do you drive per year?</p>\n        <div data-slot=\"miles\"></div>\n      </div>\n      <div class=\"say-group\" data-lob-alt=\"home\">\n        <p class=\"say\">What type of plumbing does the home have? Copper, galvanized, PVC, or PEX?</p>\n        <div data-slot=\"plumbing\"></div>\n      </div>\n      <div>\n        <div class=\"pick\">Anything else worth passing to the agent</div>\n        <div data-slot=\"notes\" style=\"margin-top:5px\"></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"step\">\n    <div class=\"step-head\">\n      <div class=\"num\">6</div>\n      <h2>Hand off to the sales agent</h2>\n    </div>\n    <div class=\"step-body say-group\">\n      <p class=\"say\">I have <span class=\"coach\">[Sales Agent's Name]</span> on the line with us, who's working on your quote and will go over your discounts to make sure we're getting you the best price possible.</p>\n      <div class=\"note\">If the prospect gave you new information, share it with the sales agent. Hit <strong>Copy CRM note</strong> and paste it into the Teams channel conversation before you drop off.</div>\n    </div>\n  </section>\n\n  </div>\n\n</main>\n\n<aside class=\"drawer\" id=\"drawer\" aria-label=\"Opening objections\">\n  <div class=\"drawer-head\">\n    <div class=\"drawer-title\">\n      <h2>Opening objections</h2>\n      <span class=\"count\" id=\"objCount\">16 of 16</span>\n      <button class=\"drawer-close\" id=\"btnObjClose\" type=\"button\" aria-label=\"Close objections\">&times;</button>\n    </div>\n    <input type=\"text\" id=\"objFilter\" aria-label=\"Filter objections\" placeholder=\"Filter: email, busy, interested, rate&hellip;\" autocomplete=\"off\">\n  </div>\n\n  <div class=\"drawer-body\" id=\"objList\">\n\n    <details class=\"obj\" name=\"objection\" data-k=\"busy time talk no time\">\n      <summary><span class=\"on\">1</span><span>I'm really busy, don't have time to talk&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Oh I'm sorry about that. We can email you the quote for you to review. Is your email <span class=\"tok\" data-tok=\"email\" data-ph=\"Email Address\"></span>?</p>\n        <p class=\"say\">Perfect, we'll send that over to you along with the <span class=\"tok\" data-tok=\"lobShort\" data-ph=\"Auto/Home\"></span> quote as well&hellip;</p>\n        <p class=\"say\">To make sure you get the best price possible, I want to see if we can apply any discounts that the system may have missed&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"email quote just send\">\n      <summary><span class=\"on\">2</span><span>Can you just email me the quote?</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>I'd be happy to do that. Is your email address <span class=\"tok\" data-tok=\"email\" data-ph=\"Email Address\"></span>?</p>\n        <p class=\"say\">To make sure we're sending you the most accurate quote to your email, I wanted to confirm&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"who is this why calling me\">\n      <summary><span class=\"on\">3</span><span>Who's this? Why are you calling me?</span></summary>\n      <div class=\"obj-body\">\n        <div class=\"alt\" data-lead=\"old\">\n          <div class=\"pick\">Old lead</div>\n          <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>This is <span class=\"tok\" data-tok=\"sdrName\" data-ph=\"Your Name\"></span> calling you from <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span>, we gave you a quote a while back, and since our rates have recently changed, I wanted to email you the updated <span class=\"tok\" data-tok=\"lobWord\" data-ph=\"Auto/Homeowners\"></span> quote that we have in the system for you. Is your email address <span class=\"tok\" data-tok=\"email\" data-ph=\"Email Address\"></span>? And your home address is <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Address\"></span>, is that right?</p>\n        </div>\n        <div class=\"alt\" data-lead=\"new\">\n          <div class=\"pick\">New internet lead</div>\n          <p class=\"say\" data-lob-alt=\"auto\"><span class=\"ack\">Acknowledge / agree</span>This is <span class=\"tok\" data-tok=\"sdrName\" data-ph=\"Your Name\"></span> calling you from <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span>, I see that you requested a car insurance quote for your <span class=\"tok\" data-tok=\"vehicles\" data-ph=\"Make/Model of Vehicle\"></span>. Is that the only car that you need a quote for, or do you have other cars that need to be insured as well?</p>\n          <p class=\"say\" data-lob-alt=\"home\"><span class=\"ack\">Acknowledge / agree</span>This is <span class=\"tok\" data-tok=\"sdrName\" data-ph=\"Your Name\"></span> calling you from <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span>, I see that you requested an insurance quote for your home on <span class=\"tok\" data-tok=\"street\" data-ph=\"Street Address\"></span>. Do you live in that home, or are you in the process of buying it?</p>\n        </div>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"didnt request quote did not\">\n      <summary><span class=\"on\">4</span><span>I didn't request a quote&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <div class=\"alt\" data-lead=\"old\">\n          <div class=\"pick\">Old lead</div>\n          <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>That's right you didn't. I wanted to give you a call because we gave you a quote a while back, and since our rates have recently changed, I wanted to email you the updated <span class=\"tok\" data-tok=\"lobWord\" data-ph=\"Auto/Homeowners\"></span> quote that we have in the system for you. Is your email address <span class=\"tok\" data-tok=\"email\" data-ph=\"Email Address\"></span>? And your home address is <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Address\"></span>, is that right?</p>\n        </div>\n        <div class=\"alt\" data-lead=\"new\">\n          <div class=\"pick\">New internet lead</div>\n          <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Oh I'm sorry about that. It could be that someone requested an insurance quote under your name&hellip; or your policy is coming up for renewal.</p>\n          <p class=\"say\">I will tell you that we've been able to help a lot of people in <span class=\"tok\" data-tok=\"city\" data-ph=\"City\"></span> switch their insurance to <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span> because we have great rates, and great coverage.</p>\n          <p class=\"say\">I did want to ask, do you:</p>\n          <p class=\"say\" data-lob-alt=\"home\">Live at <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Address\"></span>, or are you in the process of buying it?</p>\n          <p class=\"say\" data-lob-alt=\"auto\">Drive the <span class=\"tok\" data-tok=\"vehicles\" data-ph=\"Make/Model of Vehicle\"></span>?</p>\n        </div>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"never worked with you dont know\">\n      <summary><span class=\"on\">5</span><span>I never worked with you&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>That's right! You and I have never talked before, but we gave you a quote a while back, and since our rates have recently changed, I wanted to email you the updated <span class=\"tok\" data-tok=\"lobWord\" data-ph=\"Auto/Homeowners\"></span> quote that we have in the system for you. Is your email address <span class=\"tok\" data-tok=\"email\" data-ph=\"Email Address\"></span>? And your home address is <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Address\"></span>, is that right?</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"not interested no thanks\">\n      <summary><span class=\"on\">6</span><span>I'm not interested&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>I totally get it. Getting a <span class=\"tok\" data-tok=\"lobThing\" data-ph=\"Car/Home\"></span> insurance quote can take forever when you have to answer a lot of questions and start the quote from scratch. The good news is that we have most of your information here, and we can share the price with you in just a moment but I wanted to see if we can apply any additional discounts that the system may have missed. It looks like&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"already have insurance covered insured\">\n      <summary><span class=\"on\">7</span><span>I already have insurance&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <div class=\"pick\">Acknowledge, pick one</div>\n        <p class=\"say\">Who are you insured with?</p>\n        <p class=\"say\">That's right you do! It looks like you're insured with <span class=\"tok\" data-tok=\"insurer\" data-ph=\"Current Insurer\"></span>, is that right?</p>\n        <p class=\"say\">I will tell you that we've been able to help a lot of people in <span class=\"tok\" data-tok=\"city\" data-ph=\"City\"></span> switch their insurance to <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span> because we have great rates, and great coverage.</p>\n        <p class=\"say\">I did want to ask, do you:</p>\n        <p class=\"say\" data-lob-alt=\"home\">Live at <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Address\"></span>, or are you in the process of buying it?</p>\n        <p class=\"say\" data-lob-alt=\"auto\">Drive the <span class=\"tok\" data-tok=\"vehicles\" data-ph=\"Make/Model of Vehicle\"></span>?</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"just renewed policy renewal\">\n      <summary><span class=\"on\">8</span><span>I just renewed my policy&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Ah, got it. Did you pay in full or do you pay monthly?</p>\n        <p class=\"say\">Well, since we have your quote already started, we can share how much it would cost if you insured your <span class=\"tok\" data-tok=\"lobThing\" data-ph=\"Car/Home\"></span> with our agency. If you like our price and coverage, we can help you switch over to us, and <span class=\"tok\" data-tok=\"insurer\" data-ph=\"Current Carrier\"></span> will send you a refund for what you prepaid for in advance. It's very easy, and we will help you with that. It looks like&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"just paid for insurance payment\">\n      <summary><span class=\"on\">9</span><span>I just paid for my insurance&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Ah, got it. Did you pay in full or do you pay monthly?</p>\n        <p class=\"say\">Well, since we have your quote already started, we can share how much it would cost if you insured your <span class=\"tok\" data-tok=\"lobThing\" data-ph=\"Car/Home\"></span> with our agency. If you like our price and coverage, we can help you switch over to us, and <span class=\"tok\" data-tok=\"insurer\" data-ph=\"New Carrier\"></span> will send you a refund for what you prepaid for in advance. It's very easy, and we will help you with that. It looks like&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"signed up different company switched already bought\">\n      <summary><span class=\"on\">10</span><span>I just signed up with a different company&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Ah, got it. Who did you end up signing up with?</p>\n        <p class=\"say\">Well, since we have your quote already started, we can share how much it would cost if you insured your <span class=\"tok\" data-tok=\"lobThing\" data-ph=\"Car/Home\"></span> with our agency. If you like our price and coverage, we can help you switch over to us, and <span class=\"tok\" data-tok=\"insurer\" data-ph=\"New Carrier\"></span> will send you a refund for the unearned premium. It's very easy, and we will help you with that. It looks like&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"how do you have my information privacy where get number\">\n      <summary><span class=\"on\">11</span><span>How do you have my information?</span></summary>\n      <div class=\"obj-body\">\n        <div class=\"alt\" data-lead=\"old\">\n          <div class=\"pick\">Old lead</div>\n          <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>That's a great question! We gave you an insurance quote a while back and since our rates have recently changed, I wanted to email you an updated <span class=\"tok\" data-tok=\"lobWord\" data-ph=\"Auto/Homeowners\"></span> quote that we have in the system for you. Is your email address <span class=\"tok\" data-tok=\"email\" data-ph=\"Email Address\"></span>? And your home address is <span class=\"tok\" data-tok=\"addressFull\" data-ph=\"Address\"></span>, is that right?</p>\n        </div>\n        <div class=\"alt\" data-lead=\"new\">\n          <div class=\"pick\">New lead</div>\n          <p class=\"say\" data-lob-alt=\"auto\">That's a great question! We got a request for a car insurance quote for a <span class=\"tok\" data-tok=\"vehicles\" data-ph=\"Make/Model of Vehicle\"></span>. Is that the only car that you need a quote for, or do you have other cars that need to be insured as well?</p>\n          <p class=\"say\" data-lob-alt=\"home\">That's a great question! We got a request for an insurance quote for your home on <span class=\"tok\" data-tok=\"street\" data-ph=\"Street Address\"></span>. Do you live in that home, or are you in the process of buying it?</p>\n        </div>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"spouse wife husband takes care of the bill partner\">\n      <summary><span class=\"on\">12</span><span>My spouse takes care of the bill&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Oh that's great, I'm sure it makes things easier for you! Well I'm looking at the quote that we've started for you, and we'll share the price with you so you can pass it along to <span class=\"tok\" data-tok=\"spouse\" data-ph=\"Spouse's Name\"></span>, but first I want to see if we can apply any additional discounts that the system may have missed. It looks like&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"bad experience complaint upset angry\">\n      <summary><span class=\"on\">13</span><span>I've had a bad experience with your company&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Oh I am so sorry to hear that! What happened?</p>\n        <div class=\"pick\">Politely intervene and say</div>\n        <p class=\"say\">I'm so sorry to hear that, I know that I wouldn't be happy if that happened to me. I think it's important for you to know that I'm calling you from a completely different <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span> office, and we do things very differently here. I can assure you that your experience with us will never be anything short of amazing. That I can promise you.</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"give me your price first how much cost\">\n      <summary><span class=\"on\">14</span><span>Give me your price first&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>I'd be happy to do that! We'll share the price with you in just a moment, but first I want to see if we can apply any additional discounts that the system may have missed. It looks like&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"no one can beat my rate cheaper price\">\n      <summary><span class=\"on\">15</span><span>No one can beat my rate&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Well, challenge accepted!</p>\n        <p class=\"say\">I will tell you that we've been able to help a lot of people in <span class=\"tok\" data-tok=\"city\" data-ph=\"City\"></span> switch their insurance to <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span> because we have great rates, and great coverage.</p>\n        <p class=\"say\">We're working on your quote right now, before we share our final price with you, I wanted to confirm a few details to make sure you get the best price possible. It looks like&hellip;</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <details class=\"obj\" name=\"objection\" data-k=\"wrong number not me who\">\n      <summary><span class=\"on\">16</span><span>You called the wrong number&hellip;</span></summary>\n      <div class=\"obj-body\">\n        <p class=\"say\"><span class=\"ack\">Acknowledge / agree</span>Do you know who <span class=\"tok\" data-tok=\"prospect\" data-ph=\"Prospect's Name\"></span> is? Does s/he live in your household?</p>\n        <p class=\"say\"><strong>Yes:</strong> May I speak to him/her?</p>\n        <p class=\"say\"><strong>No:</strong> Oh got it, it looks like they might have entered a wrong number by mistake. I'm sorry about that. I didn't catch your name, what is your name?</p>\n        <p class=\"say\">Well, [their name], since our rates have recently changed, and I have you on the line, if you'd like we can give you a quote and let you know how much it would cost if you switched your insurance to <span class=\"tok\" data-tok=\"company\" data-ph=\"Your Company\"></span>. Who are you currently insured with?</p>\n        <div class=\"back\">Get back into the script and ask a question</div>\n      </div>\n    </details>\n\n    <div class=\"nores\" id=\"objNone\" hidden>No objection matches that.</div>\n  </div>\n</aside>\n</div>\n\n</div>\n\n<div class=\"scrim\" id=\"scrim\"></div>\n\n\n\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<button class=\"btn\" id=\"btnTheme\" type=\"button\" style=\"position:fixed;bottom:8px;right:8px;z-index:1000;padding:4px 7px;font-size:11px;line-height:18px\">Dark mode</button>\n<script>\n(function(){\n  var COMPANY = 'Farmers Insurance';\n  var PERSIST = ['sdrName'];\n  var CALL    = ['prospect','vehicles','street','city','state','zip','dob','email','spouse'];\n  var DISCOVERY = ['d_carrier','d_reason','d_occupation','d_miles','d_plumbing','d_business','d_notes'];\n  var KEY = 'sdr-script-setup-v1';\n\n  function el(id){ return document.getElementById(id); }\n  function val(id){ var e = el('f_'+id); return e ? e.value.trim() : ''; }\n  function join(parts){ return parts.filter(function(p){return p;}).join(', '); }\n\n  function readableDob(value){\n    var raw = String(value || '').trim();\n    var iso = raw.match(/^(\\d{4})[\\/-](\\d{1,2})[\\/-](\\d{1,2})$/);\n    var us = raw.match(/^(\\d{1,2})[\\/-](\\d{1,2})[\\/-](\\d{4})$/);\n    if(!iso && !us) return raw;\n    var year = Number(iso ? iso[1] : us[3]);\n    var month = Number(iso ? iso[2] : us[1]);\n    var day = Number(iso ? iso[3] : us[2]);\n    var leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);\n    var days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];\n    if(year < 1 || month < 1 || month > 12 || day < 1 || day > days[month-1]) return raw;\n    var months = ['January','February','March','April','May','June','July','August','September','October','November','December'];\n    var yyyy = String(year).padStart(4, '0');\n    return String(month).padStart(2, '0') + '/' + String(day).padStart(2, '0') + '/' + yyyy +\n      ' (' + months[month-1] + ' ' + day + ', ' + yyyy + ')';\n  }\n\n  var COMPOSED = {\n    prospect: function(){ return val('prospect').split(/\\s+/)[0]; },\n    dob: function(){ return readableDob(val('dob')); },\n    company: function(){ return COMPANY; },\n    addressFull: function(){ return join([val('street'), val('city'), val('zip')]); },\n    cityStateZip: function(){ return join([val('city'), val('state'), val('zip')]); },\n    lobWord: function(){ return currentLob() === 'auto' ? 'Auto' : 'Homeowners'; },\n    lobThing: function(){ return currentLob() === 'auto' ? 'Car' : 'Home'; },\n    lobShort: function(){ return currentLob() === 'auto' ? 'Auto' : 'Home'; },\n    // agency runs on Pacific time regardless of the SDR's machine\n    greet: function(){\n      var h;\n      try{\n        h = parseInt(new Intl.DateTimeFormat('en-US', {hour:'numeric', hour12:false, timeZone:'America/Los_Angeles'}).format(new Date()), 10);\n      }catch(e){ h = new Date().getHours(); }\n      return h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening';\n    },\n    insurer: function(){ return el('d_carrier') ? el('d_carrier').value.trim() : ''; }\n  };\n\n  function render(){\n    var toks = document.querySelectorAll('.tok');\n    for(var i=0;i<toks.length;i++){\n      var t = toks[i], k = t.getAttribute('data-tok');\n      var v = COMPOSED[k] ? COMPOSED[k]() : val(k);\n      if(v){ t.textContent = v; t.classList.remove('empty'); }\n      else { t.textContent = '[' + t.getAttribute('data-ph') + ']'; t.classList.add('empty'); }\n    }\n  }\n\n  function agency(){ var t = el('agencyName').textContent.trim(); return t === '\\u2014' ? '' : t; }\n  function setAgency(name){ el('agencyName').textContent = (name && String(name).trim()) || '\\u2014'; }\n\n  function save(){\n    try{\n      var o = {agency: agency()};\n      PERSIST.forEach(function(k){ o[k] = val(k); });\n      localStorage.setItem(KEY, JSON.stringify(o));\n    }catch(e){}\n  }\n\n  function load(){\n    var o = null;\n    try{ o = JSON.parse(localStorage.getItem(KEY) || 'null'); }catch(e){}\n    if(!o) return false;\n    PERSIST.forEach(function(k){ if(el('f_'+k) && o[k]) el('f_'+k).value = o[k]; });\n    if(o.agency) setAgency(o.agency);\n    return !!o.sdrName;\n  }\n\n  function updateThemeButton(){\n    el('btnTheme').textContent = document.documentElement.dataset.theme === 'dark' ? 'Light mode' : 'Dark mode';\n  }\n  el('btnTheme').addEventListener('click', function(){\n    var theme = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';\n    document.documentElement.dataset.theme = theme;\n    try { localStorage.setItem('sdr-script-theme-v1', theme); } catch (_) {}\n    updateThemeButton();\n  });\n  updateThemeButton();\n\n  // The userscript routes these clicks to the selected Ricochet popup.\n  document.querySelectorAll('button[data-action]').forEach(function(b){\n    b.addEventListener('click', function(){\n      window.dispatchEvent(new CustomEvent('sdr:action', {detail: {action:b.dataset.action}}));\n      if(b.dataset.action === 'notify') window.dispatchEvent(new CustomEvent('sdr:notify', {detail:window.SDR.get()}));\n    });\n  });\n\n  // wire inputs\n  PERSIST.concat(CALL).forEach(function(k){\n    var e = el('f_'+k);\n    if(!e) return;\n    e.addEventListener('input', function(){\n      render();\n      if(PERSIST.indexOf(k) !== -1) save();\n    });\n  });\n\n  // line of business tabs\n  function setLob(lob){\n    document.querySelectorAll('[data-lob]').forEach(function(b){\n      b.setAttribute('aria-selected', b.getAttribute('data-lob') === lob ? 'true' : 'false');\n    });\n    document.querySelectorAll('[data-panel]').forEach(function(p){\n      p.hidden = p.getAttribute('data-panel') !== lob;\n    });\n    document.querySelectorAll('[data-lob-alt]').forEach(function(a){\n      a.hidden = a.getAttribute('data-lob-alt') !== lob;\n    });\n    render();\n  }\n\n  var MODES = {\n    'new': ['New internet lead', 'They asked for a quote. Confirm details, stall, transfer.'],\n    'old': ['Old lead / X-date / requote', 'Quoted before, could not help at the time. Rates changed, requote.']\n  };\n  // one set of capture inputs, moved into whichever script is showing\n  var SLOTS = ['carrier','reason','occupation','miles','plumbing','business','notes'];\n  function moveCaptures(lead){\n    SLOTS.forEach(function(k){\n      var inp = el('d_' + k);\n      var slot = document.querySelector('[data-script=\"' + lead + '\"] [data-slot=\"' + k + '\"]');\n      if(inp && slot && inp.parentNode !== slot) slot.appendChild(inp);\n    });\n  }\n\n  function setLead(lead){\n    document.querySelectorAll('[data-lead]').forEach(function(n){\n      if(n.tagName === 'BUTTON'){\n        n.setAttribute('aria-selected', n.getAttribute('data-lead') === lead ? 'true' : 'false');\n      } else {\n        n.hidden = n.getAttribute('data-lead') !== lead;\n      }\n    });\n    moveCaptures(lead);\n    document.querySelectorAll('[data-script]').forEach(function(sc){\n      sc.hidden = sc.getAttribute('data-script') !== lead;\n    });\n    document.body.setAttribute('data-mode', lead);\n    el('modeName').textContent = MODES[lead][0];\n    el('modeWhat').textContent = MODES[lead][1];\n    render();\n  }\n  document.querySelectorAll('button[data-lead]').forEach(function(b){\n    b.addEventListener('click', function(){ setLead(b.getAttribute('data-lead')); });\n  });\n  document.querySelectorAll('[data-lob]').forEach(function(b){\n    b.addEventListener('click', function(){ setLob(b.getAttribute('data-lob')); });\n  });\n\n  function setOwn(own){\n    document.querySelectorAll('[data-own]').forEach(function(b){\n      b.setAttribute('aria-selected', b.getAttribute('data-own') === own ? 'true' : 'false');\n    });\n    document.querySelectorAll('[data-own-panel]').forEach(function(p){\n      p.hidden = p.getAttribute('data-own-panel') !== own;\n    });\n  }\n  document.querySelectorAll('[data-own]').forEach(function(b){\n    b.addEventListener('click', function(){ setOwn(b.getAttribute('data-own')); });\n  });\n\n  function currentLob(){\n    var b = document.querySelector('[data-lob][aria-selected=\"true\"]');\n    return b ? b.getAttribute('data-lob') : 'home';\n  }\n  function currentLead(){\n    var b = document.querySelector('button[data-lead][aria-selected=\"true\"]');\n    return b ? b.getAttribute('data-lead') : 'new';\n  }\n\n  // current carrier answer feeds the objection scripts too\n  if(el('d_carrier')) el('d_carrier').addEventListener('input', render);\n\n  // the rail sits under the sticky bar, whose height depends on wrapping\n  var narrow = window.matchMedia('(max-width: 1200px)');\n  function syncBarHeight(){\n    document.documentElement.style.setProperty('--barh', document.querySelector('.bar').offsetHeight + 'px');\n  }\n  window.addEventListener('resize', syncBarHeight);\n  if(document.fonts && document.fonts.ready) document.fonts.ready.then(syncBarHeight);\n  syncBarHeight();\n\n  // objections: a rail on desktop, a slide-over drawer when narrow\n  function setDrawer(open){\n    el('drawer').classList.toggle('open', open);\n    el('scrim').classList.toggle('open', open);\n    el('btnObj').setAttribute('aria-expanded', open ? 'true' : 'false');\n    // only hide it from AT when it is actually an off-screen drawer\n    if(narrow.matches && !open) el('drawer').setAttribute('aria-hidden', 'true');\n    else el('drawer').removeAttribute('aria-hidden');\n    if(open) el('objFilter').focus();\n  }\n  narrow.addEventListener('change', function(){ setDrawer(false); });\n  el('btnObj').addEventListener('click', function(){ setDrawer(!el('drawer').classList.contains('open')); });\n  el('btnObjClose').addEventListener('click', function(){ setDrawer(false); });\n  el('scrim').addEventListener('click', function(){ setDrawer(false); });\n  document.addEventListener('keydown', function(e){\n    if(e.key === 'Escape' && el('drawer').classList.contains('open')) setDrawer(false);\n  });\n\n  // one objection open at a time. <details name> does this natively in Chrome 120+; this covers older builds.\n  el('objList').addEventListener('toggle', function(e){\n    if(!e.target.open || !e.target.classList.contains('obj')) return;\n    document.querySelectorAll('.obj[open]').forEach(function(o){ if(o !== e.target) o.open = false; });\n  }, true);\n\n  el('objFilter').addEventListener('input', function(){\n    var q = this.value.trim().toLowerCase();\n    var objs = document.querySelectorAll('.obj');\n    var shown = 0;\n    objs.forEach(function(o){\n      var hay = (o.getAttribute('data-k') + ' ' + o.querySelector('summary').textContent).toLowerCase();\n      var match = !q || hay.indexOf(q) !== -1;\n      o.hidden = !match;\n      if(match) shown++;\n    });\n    el('objNone').hidden = shown > 0;\n    el('objCount').textContent = shown + ' of ' + objs.length;\n  });\n\n  // toast\n  var toastTimer;\n  function toast(msg){\n    var t = el('toast');\n    t.textContent = msg;\n    t.classList.add('show');\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(function(){ t.classList.remove('show'); }, 2200);\n  }\n\n  // copy note\n  function buildNote(){\n    var lob = currentLob() === 'auto' ? 'Auto' : 'Homeowners';\n    var lines = [];\n    lines.push('SDR CALL NOTE');\n    lines.push('SDR: ' + (val('sdrName') || '-'));\n    lines.push('Date: ' + new Date().toLocaleString());\n    lines.push('Script: ' + (currentLead() === 'old' ? 'Old lead / requote' : 'New internet lead'));\n    lines.push('Line of business: ' + lob);\n    lines.push('Prospect: ' + (val('prospect') || '-'));\n    if(val('vehicles')) lines.push('Vehicles: ' + val('vehicles'));\n    var addr = join([val('street'), val('city'), val('state'), val('zip')]);\n    if(addr) lines.push('Address: ' + addr);\n    if(val('dob')) lines.push('DOB: ' + val('dob'));\n    if(val('email')) lines.push('Email: ' + val('email'));\n    if(val('spouse')) lines.push('Spouse: ' + val('spouse'));\n    lines.push('');\n    lines.push('DISCOVERY');\n    var qs = [\n      ['Current carrier', 'd_carrier'],\n      ['Why shopping today', 'd_reason'],\n      ['Occupation', 'd_occupation'],\n      ['Miles per year', 'd_miles'],\n      ['Plumbing type', 'd_plumbing'],\n      ['Business on property', 'd_business'],\n      ['Other notes', 'd_notes']\n    ];\n    var any = false;\n    qs.forEach(function(q){\n      var v = el(q[1]) ? el(q[1]).value.trim() : '';\n      if(v){ lines.push(q[0] + ': ' + v); any = true; }\n    });\n    if(!any) lines.push('(no discovery answers captured)');\n    return lines.join('\\n');\n  }\n\n  function copyText(text){\n    if(navigator.clipboard && navigator.clipboard.writeText){\n      navigator.clipboard.writeText(text).then(function(){ toast('Note copied'); }, fallback);\n    } else { fallback(); }\n    function fallback(){\n      var ta = document.createElement('textarea');\n      ta.value = text;\n      ta.setAttribute('readonly','');\n      ta.style.position = 'fixed';\n      ta.style.opacity = '0';\n      document.body.appendChild(ta);\n      ta.select();\n      var ok = false;\n      try{ ok = document.execCommand('copy'); }catch(e){}\n      document.body.removeChild(ta);\n      toast(ok ? 'Note copied' : 'Copy blocked, select the text manually');\n    }\n  }\n\n  el('btnCopy').addEventListener('click', function(){ copyText(buildNote()); });\n\n  el('btnReset').addEventListener('click', function(){\n    CALL.forEach(function(k){ if(el('f_'+k)) el('f_'+k).value = ''; });\n    DISCOVERY.forEach(function(k){ if(el(k)) el(k).value = ''; });\n    setOwn('owns');\n    setDrawer(false);\n    el('objFilter').value = '';\n    document.querySelectorAll('.obj').forEach(function(o){ o.hidden = false; o.open = false; });\n    el('objNone').hidden = true;\n    el('objCount').textContent = '16 of 16';\n    document.querySelectorAll('button[data-notify]').forEach(function(b){ b.classList.remove('fired'); });\n    render();\n    if(!document.body.classList.contains('fields-hidden') && el('f_prospect')) el('f_prospect').focus();\n    window.scrollTo({top:0, behavior:'smooth'});\n    toast('Cleared for next call');\n  });\n\n  // ---- fields toggle: hidden once a userscript is filling them ----\n  function setFields(hidden){\n    document.body.classList.toggle('fields-hidden', hidden);\n    el('btnFields').setAttribute('aria-expanded', hidden ? 'false' : 'true');\n    el('btnFields').textContent = hidden ? 'Show fields' : 'Hide fields';\n    syncBarHeight();\n  }\n  el('btnFields').addEventListener('click', function(){\n    setFields(!document.body.classList.contains('fields-hidden'));\n  });\n\n  // ---- public API for the Tampermonkey userscript ----\n  // Setting input.value directly does NOT fire an input event, so the script\n  // text would never update. Always go through SDR.fill().\n  var FILLABLE = PERSIST.concat(CALL);\n  window.SDR = {\n    fill: function(data){\n      data = data || {};\n      FILLABLE.forEach(function(k){\n        if(data[k] === undefined || data[k] === null) return;\n        var e = el('f_' + k);\n        if(e) e.value = String(data[k]);\n        if(PERSIST.indexOf(k) !== -1) save();\n      });\n      var lob  = String(data.lob  || '').toLowerCase();\n      var lead = String(data.lead || '').toLowerCase();\n      var owns = String(data.owns || '').toLowerCase();\n      if(lob)  setLob(/^home/.test(lob) ? 'home' : 'auto');\n      if(lead) setLead(lead === 'old' ? 'old' : 'new');\n      if(owns) setOwn(/^buy/.test(owns) ? 'buying' : 'owns');\n      if(data.agency !== undefined && data.agency !== null){ setAgency(data.agency); save(); }\n      var carrier = data.carrier !== undefined ? data.carrier : data.insurer;\n      if(carrier !== undefined && carrier !== null && el('d_carrier')) el('d_carrier').value = String(carrier);\n      render();\n      // the userscript is driving the fields, so get them out of the way\n      if(el('f_prospect').value.trim()) setFields(true);\n      return window.SDR.get();\n    },\n    get: function(){\n      var out = {lob: currentLob(), lead: currentLead(), agency: agency(), owns: document.querySelector('[data-own][aria-selected=\"true\"]')?.getAttribute('data-own') || 'owns'};\n      FILLABLE.forEach(function(k){ out[k] = val(k); });\n      DISCOVERY.forEach(function(k){ out[k.slice(2)] = el(k) ? el(k).value.trim() : ''; });\n      return out;\n    },\n    restore: function(data){\n      window.SDR.fill(data);\n      DISCOVERY.forEach(function(k){ if(el(k)) el(k).value = String(data[k.slice(2)] || ''); });\n      render();\n    },\n    note: function(){ return buildNote(); },\n    setLob: setLob,\n    setLead: setLead,\n    reset: function(){ el('btnReset').click(); },\n    setAgency: function(name){ setAgency(name); save(); },\n    setActions: function(options){\n      document.querySelectorAll('button[data-action]').forEach(function(b){\n        b.disabled = !options.available || options.busy || (b.dataset.action === 'notify' && !options.agencyKnown);\n      });\n      document.querySelectorAll('[data-action-status]').forEach(function(e){e.textContent = options.message || '';});\n    },\n    onNotify: function(fn){ window.addEventListener('sdr:notify', function(e){ fn(e.detail); }); },\n    showFields: function(show){ setFields(!show); }\n  };\n\n  load();\n  setLob('home');\n  setOwn('owns');\n  setLead('new');\n  setDrawer(false);\n  // always hidden on load; the userscript fills them, the button reveals them for this session\n  setFields(true);\n  render();\n  window.dispatchEvent(new CustomEvent('sdr:ready', {detail: window.SDR}));\n})();\n</script>\n\n</body>\n</html>\n";
function clean(value) {
  return String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
}

function buildPrefill(lead, sdrName) {
  const data = { sdrName: clean(sdrName), prospect: clean(lead.contact) };
  if (clean(lead.agency)) data.agency = clean(lead.agency).split(/\s+/)[0];
  for (const key of ['dob', 'email', 'vehicles', 'street', 'city', 'state', 'zip', 'spouse', 'carrier']) {
    data[key] = clean(lead[key]);
  }
  const mode = clean(lead.lead).toLowerCase();
  const lob = clean(lead.lob).toLowerCase();
  const owns = clean(lead.owns).toLowerCase();
  if (['old', 'x-date', 'xdate', 'requote'].includes(mode)) data.lead = 'old';
  if (['new', 'new internet lead'].includes(mode)) data.lead = 'new';
  if (['home', 'homeowner', 'homeowners'].includes(lob)) data.lob = 'home';
  if (lob === 'auto') data.lob = 'auto';
  if (owns === 'buying') data.owns = 'buying';
  if (['own', 'owns'].includes(owns)) data.owns = 'owns';
  const vendor = clean(lead.vendor);
  if (vendor) {
    data.lead = /rq-/i.test(vendor) ? 'old' : 'new';
    data.lob = /auto/i.test(vendor) ? 'auto' : 'home';
  }
  return Object.fromEntries(Object.entries(data).filter(([, value]) => value !== ''));
}

function createDisplaySync() {
  let lastApi, lastKey = '', previous = {};
  return {
    apply(api, payload) {
      if (!api || !['fill', 'get', 'reset'].every(key => typeof api[key] === 'function') || !payload || !payload.leadKey) return false;
      const incoming = payload.prefill || {};
      const changedLead = api !== lastApi || payload.leadKey !== lastKey;
      const delta = {};
      for (const [key, value] of Object.entries(incoming)) {
        if (value == null || value === '') continue;
        if (changedLead || value !== previous[key]) delta[key] = value;
      }
      if (changedLead) api.reset();
      if (changedLead || Object.keys(delta).length) api.fill(delta);
      lastApi = api;
      lastKey = payload.leadKey;
      // Keep the last observed non-empty value across partial DOM updates.
      previous = changedLead ? { ...incoming } : { ...previous, ...Object.fromEntries(Object.entries(incoming).filter(([, value]) => value != null && value !== '')) };
      return true;
    }
  };
}


const PAYLOAD_KEY = 'tmRicochetSdrV2Payload';
const HEARTBEAT_KEY = 'tmRicochetSdrV2Heartbeat';
const OPEN_KEY = 'tmRicochetSdrV2OpenRequest';
const REP_KEY = 'tmRicochetCallScriptRep';
const ACTION_KEY = 'tmRicochetSdrAction';
const RESULT_KEY = 'tmRicochetSdrActionResult';
const TEAM_LABELS = {Carlos:'to Carlos Teams', Ulises:'to Ulises Teams', Stefanie:'to Stefanie Teams'};
const DISPLAY_HASH = '#tm-auto-shop-script-window';
const DISPLAY_URL = 'https://example.com/' + DISPLAY_HASH;
const TYPE = 'ricochet-sdr-v2';

if (location.hostname === 'example.com' && location.hash === DISPLAY_HASH) startDisplay();
else if (location.hostname === 'giainc.ricochet.me') startController();

function readPayload() {
  try {
    const payload = JSON.parse(GM_getValue(PAYLOAD_KEY, 'null'));
    return payload && payload.type === TYPE && payload.leadKey ? payload : null;
  } catch (_) { return null; }
}

function startDisplay() {
  document.title = 'SDR Transfer Script';
  document.body.replaceChildren();
  const style = document.createElement('style');
  style.textContent = 'html,body{margin:0;width:100%;height:100%;overflow:hidden}body{display:flex;flex-direction:column}#ricochet-sdr-frame{width:100%;flex:1;min-height:0;border:0}#ricochet-leads{padding:6px 10px;background:#edf3f1;display:flex;gap:6px;flex-wrap:wrap;font:12px system-ui}#ricochet-leads[hidden]{display:none}#ricochet-leads button{font:inherit;padding:5px 9px;border:1px solid #708c80;border-radius:5px;background:white;color:#182e25;cursor:pointer}#ricochet-leads button[aria-pressed=true]{background:#245f48;color:white}#ricochet-sync-status{position:fixed;bottom:8px;left:8px;max-width:calc(100vw - 130px);padding:5px 9px;border-radius:5px;background:#12201ce8;color:white;font:12px system-ui;pointer-events:none;z-index:9999}';
  document.head.appendChild(style);
  const frame = document.createElement('iframe');
  frame.id = 'ricochet-sdr-frame';
  frame.title = 'SDR Transfer Script';
  frame.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms');
  const status = document.createElement('div');
  status.id = 'ricochet-sync-status';
  status.setAttribute('role', 'status');
  status.textContent = 'Waiting for Ricochet lead…';
  const switcher = document.createElement('nav');
  switcher.id = 'ricochet-leads';
  switcher.setAttribute('aria-label', 'Switch lead');
  switcher.hidden = true;
  const syncs = new Map(), drafts = new Map();
  let selectedKey = '', activeKey = '', activeApi, choicesSignature = '';
  let focusedLeadKey = '';
  let previousKeys = new Set();
  let pending = readPayload();
  let readyWindow;
  let actionPending;
  const actionMessages = new Map();
  function sendAction(event) {
    const action = event.detail?.action;
    if (!['notify','quote'].includes(action) || actionPending) return;
    const chosen = (pending?.leads || []).find(lead => lead.leadKey === selectedKey);
    if (!chosen || !pending.controllerId) return;
    const agency = chosen.prefill.agency || '';
    if (action === 'notify' && !TEAM_LABELS[agency]) return;
    actionPending = {id:crypto.randomUUID(), controllerId:pending.controllerId, leadKey:selectedKey, agency, action, sentAt:Date.now()};
    actionMessages.set(selectedKey, 'Requesting ' + (action === 'quote' ? 'Quoting / Info Form' : agency + ' Teams') + '…');
    GM_setValue(ACTION_KEY, JSON.stringify(actionPending));
    applyPending();
  }
  function checkActionResult() {
    if (!actionPending) return;
    let result;
    try { result = JSON.parse(GM_getValue(RESULT_KEY, 'null')); } catch (_) {}
    if (result?.id === actionPending.id) {
      actionMessages.set(actionPending.leadKey, result.message);
      actionPending = null;
    } else if (Date.now() - actionPending.sentAt > 10000) {
      actionMessages.set(actionPending.leadKey, 'No confirmation from Ricochet. Check its webhook result before trying again.');
      actionPending = null;
    }
  }
  function applyPending() {
    // Access the template's page-world API when the userscript runs in an isolated world.
    const page = typeof unsafeWindow === 'undefined' ? window : unsafeWindow;
    const view = page.document.getElementById(frame.id)?.contentWindow;
    if (!view) return;
    if (view !== readyWindow) {
      readyWindow = view;
      view.addEventListener('sdr:ready', applyPending);
      view.addEventListener('sdr:action', sendAction);
    }
    if (!pending) return;
    try {
      const leads = pending.leads || [pending];
      const keys = new Set(leads.map(lead => lead.leadKey));
      const addedLead = leads.filter(lead => !previousKeys.has(lead.leadKey)).at(-1);
      if (addedLead) selectedKey = addedLead.leadKey;
      previousKeys = keys;
      for (const key of syncs.keys()) if (!keys.has(key)) { drafts.delete(key); syncs.delete(key); }
      if (!keys.has(selectedKey)) selectedKey = leads.at(-1)?.leadKey || '';
      const chosen = leads.find(lead => lead.leadKey === selectedKey);
      const signature = JSON.stringify([selectedKey, leads.map(lead => [lead.leadKey, lead.label])]);
      if (signature !== choicesSignature) {
        switcher.replaceChildren();
        switcher.hidden = leads.length < 2;
        for (const lead of leads) {
          const button = document.createElement('button');
          const name = lead.prefill.prospect || lead.label || 'Lead';
          const first = name.split(/\s+/)[0];
          const duplicate = leads.filter(item => (item.prefill.prospect || item.label || 'Lead').split(/\s+/)[0] === first).length > 1;
          button.textContent = 'Switch to ' + (duplicate ? name : first);
          button.title = name;
          button.setAttribute('aria-pressed', String(lead.leadKey === selectedKey));
          button.onclick = () => { selectedKey = lead.leadKey; applyPending(); };
          switcher.appendChild(button);
        }
        choicesSignature = signature;
      }
      const api = view.SDR;
      api?.setActions?.({available:!!chosen && !!pending.controllerId, agencyKnown:!!TEAM_LABELS[chosen?.prefill.agency], busy:!!actionPending,
        message:actionMessages.get(selectedKey) || (!chosen ? 'Open a lead box in Ricochet to use these actions.' : !TEAM_LABELS[chosen.prefill.agency] ? 'Agency unknown: Teams notification unavailable.' : '')});
      if (!chosen) {
        focusedLeadKey = '';
        document.title = 'No open lead | SDR Transfer Script';
        status.textContent = 'No open Ricochet lead box' + (activeKey ? ' · Previous script retained' : '');
        if (!activeKey && api?.get().agency && typeof api.setAgency === 'function') api.setAgency('');
        return;
      }
      if (!api) return;
      if (activeApi !== api) { drafts.clear(); syncs.clear(); activeKey = ''; activeApi = api; }
      if (activeKey !== selectedKey) {
        if (activeKey && keys.has(activeKey)) drafts.set(activeKey, api.get());
        api.reset();
        if (drafts.has(selectedKey)) api.restore(drafts.get(selectedKey));
        activeKey = selectedKey;
      }
      if (!syncs.has(selectedKey)) syncs.set(selectedKey, createDisplaySync());
      if (!syncs.get(selectedKey).apply(api, chosen)) return;
      const agency = chosen.prefill.agency || '';
      if (api.get().agency !== agency && typeof api.setAgency === 'function') api.setAgency(agency);
      const label = chosen.prefill.prospect || chosen.label || 'Lead';
      document.title = label + ' | SDR Transfer Script';
      const manual = !chosen.prefill.lead || !chosen.prefill.lob;
      status.textContent = 'Synced: ' + label + (manual ? ' · Check New/Old and Home/Auto' : '');
      if (focusedLeadKey !== selectedKey) {
        focusedLeadKey = selectedKey;
        window.focus();
        window.opener?.postMessage({type:'ricochet-sdr-focus', controllerId:pending.controllerId, leadKey:selectedKey}, 'https://giainc.ricochet.me');
      }
    } catch (error) {
      status.textContent = 'Sync failed; waiting to retry';
      console.error('[Ricochet SDR]', error);
    }
  }
  frame.addEventListener('load', applyPending);
  frame.srcdoc = TEMPLATE_HTML;
  document.body.append(switcher, frame, status);
  if (typeof GM_addValueChangeListener === 'function') {
    GM_addValueChangeListener(PAYLOAD_KEY, () => { pending = readPayload(); applyPending(); });
  }
  setInterval(() => { checkActionResult(); pending = readPayload(); applyPending(); }, 750);
  function heartbeat() { GM_setValue(HEARTBEAT_KEY, Date.now()); }
  heartbeat();
  setInterval(heartbeat, 1000);
  window.addEventListener('pagehide', () => GM_setValue(HEARTBEAT_KEY, 0));
}

function startController() {
  let displayWindow;
  const controllerId = crypto.randomUUID();
  window.addEventListener('message', event => {
    const request = event.data;
    if (event.origin !== 'https://example.com' || request?.type !== 'ricochet-sdr-focus' || request.controllerId !== controllerId || !event.source) return;
    if (displayWindow && !displayWindow.closed && event.source !== displayWindow) return;
    if (!readLeads(document).some(lead => lead.key === request.leadKey)) return;
    displayWindow = event.source;
    displayWindow.focus();
  });
  let lastAction = GM_getValue(ACTION_KEY, '');
  function handleAction() {
    const raw = GM_getValue(ACTION_KEY, '');
    if (!raw || raw === lastAction) return;
    lastAction = raw;
    let request;
    try { request = JSON.parse(raw); } catch (_) { return; }
    if (request.controllerId !== controllerId) return;
    const reply = message => GM_setValue(RESULT_KEY, JSON.stringify({id:request.id, message}));
    if (!['notify','quote'].includes(request.action) || Date.now() - request.sentAt > 10000) return reply('Request expired. Nothing clicked.');
    const matches = Array.from(document.querySelectorAll('.lead-popup-main-row, .lead-popup-main-row-opened-script'))
      .filter(root => visible(root) && readLead(root)?.key === request.leadKey);
    if (matches.length !== 1) return reply('The selected lead box is closed or ambiguous. Nothing clicked.');
    const root = matches[0], agency = buildPrefill(readLead(root), '').agency || '';
    if (request.action === 'notify' && (!TEAM_LABELS[agency] || agency !== request.agency)) return reply('Agency changed or is unknown. Nothing clicked.');
    const label = request.action === 'quote' ? 'Quoting / Info Form' : TEAM_LABELS[agency];
    const links = Array.from(root.querySelectorAll('webhook-trigger[ui="lead_popup"] a[ng-click]'))
      .filter(link => clean(link.textContent) === label && link.getAttribute('ng-click').startsWith('triggerWebhook('));
    if (links.length !== 1) return reply(label + ' is unavailable or ambiguous. Nothing clicked.');
    // Click Ricochet's own action. Its UI owns server success/error feedback.
    links[0].click();
    reply(label + ' requested. Check Ricochet for success or error.');
  }
  if (typeof GM_addValueChangeListener === 'function') GM_addValueChangeListener(ACTION_KEY, handleAction);
  setInterval(handleAction, 300);
  let candidate = '', lastSent = '';
  function publish(force = false) {
    const rep = GM_getValue(REP_KEY, '') || GM_getValue('callerName', '');
    const leads = readLeads(document).map(lead => ({leadKey:lead.key, prefill:buildPrefill(lead, rep), label:lead.name || lead.phone || ''}));
    if (!leads.length && !lastSent && !readPayload()) { candidate = ''; return; }
    const payload = {type: TYPE, controllerId, ...(leads.at(-1) || {leadKey:'none', prefill:{}}), leads};
    const signature = JSON.stringify(payload);
    // Wait for two identical snapshots so intermediate SPA renders do not switch calls.
    if (!force && signature !== candidate) { candidate = signature; return; }
    candidate = signature;
    if (signature === lastSent) return;
    GM_setValue(PAYLOAD_KEY, JSON.stringify({...payload, sentAt:Date.now()}));
    lastSent = signature;
  }
  function openDisplay(focus = false) {
    const now = Date.now();
    if (displayWindow && !displayWindow.closed) {
      if (focus) displayWindow.focus();
      return;
    }
    if (!displayWindow?.closed && now - Number(GM_getValue(HEARTBEAT_KEY, 0)) < 8000) return;
    if (!focus && !displayWindow?.closed && now - Number(GM_getValue(OPEN_KEY, 0)) < 10000) return;
    const height = Math.max(400, Math.min(950, screen.availHeight - 80));
    displayWindow = window.open(DISPLAY_URL, 'ricochet-sdr-display', 'popup=yes,width=920,height=' + height + ',resizable=yes,scrollbars=yes');
    if (displayWindow) {
      GM_setValue(OPEN_KEY, now);
      document.getElementById('ricochet-open-script-window')?.remove();
      if (focus) displayWindow.focus();
    } else if (!document.getElementById('ricochet-open-script-window')) {
      const button = document.createElement('button');
      button.id = 'ricochet-open-script-window';
      button.textContent = 'Open call script window';
      button.title = 'Chrome blocked the popup. Click to open, or allow pop-ups for Ricochet.';
      button.style.cssText = 'position:fixed;bottom:60px;right:16px;z-index:99999;padding:10px 14px;background:#16634e;color:white;border:0;border-radius:6px;font:14px system-ui;cursor:pointer';
      button.onclick = preview;
      document.body.appendChild(button);
    }
  }
  function preview() { publish(true); openDisplay(true); }
  GM_registerMenuCommand('Open SDR Script Display', () => openDisplay(true));
  GM_registerMenuCommand('Preview Current Lead (Ctrl+Alt+S)', preview);
  GM_registerMenuCommand('Set SDR Name', () => {
    const name = window.prompt('Your SDR name', GM_getValue(REP_KEY, '') || GM_getValue('callerName', ''));
    if (name !== null) { GM_setValue(REP_KEY, clean(name)); publish(true); }
  });
  document.addEventListener('keydown', event => {
    const target = event.target;
    if (event.defaultPrevented || event.repeat || !event.ctrlKey || !event.altKey || event.shiftKey || event.metaKey) return;
    if (event.code !== 'KeyS' && String(event.key).toLowerCase() !== 's') return;
    if (target && (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName))) return;
    event.preventDefault();
    preview();
  }, true);
  publish();
  setInterval(publish, 500);
  openDisplay();
  setInterval(() => openDisplay(), 5000);
  if (!clean(GM_getValue(REP_KEY, '') || GM_getValue('callerName', ''))) {
    setTimeout(() => {
      const name = window.prompt('Your SDR name for the transfer script', '');
      if (name !== null) { GM_setValue(REP_KEY, clean(name)); publish(true); }
    }, 350);
  }
}

function visible(el) {
  if (!el || el.closest('[hidden], .ng-hide')) return false;
  const style = el.ownerDocument.defaultView.getComputedStyle(el);
  const rect = el.getBoundingClientRect();
  return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
}

function readLeads(doc) {
  const popups = Array.from(doc.querySelectorAll('.lead-popup-main-row, .lead-popup-main-row-opened-script'))
    .filter(el => visible(el) && el.querySelector('#lead-popup-phone-number, .outbound-calls'));
  // Only the top Scripts/call box is a source. Never read the bottom record page.
  return Array.from(new Map(popups.map(readLead).filter(Boolean).map(lead => [lead.key, lead])).values());
}

function readLead(root) {
  // Ricochet keeps additional vehicle values on this exact top popup's Angular
  // model even when its configurable field layout omits Year. Never use the
  // bottom record's model or request another record from the server.
  let popupData;
  try {
    const page = typeof unsafeWindow === 'undefined' ? window : unsafeWindow;
    popupData = page.angular?.element(root).scope()?.lead;
  } catch (_) {}
  const value = (...names) => readField(root, names);
  const vehiclePart = (order, part) => value(order + ' Vehicle ' + part)
    || clean(popupData?.lead_field_data?.[order + '_Vehicle_' + part]);
  const text = selector => clean(Array.from(root.querySelectorAll(selector)).find(visible)?.textContent);
  const address = parsePopupAddress(text('.led-usr-addr'));
  const lead = {
    contact: value('First Name', 'Contact Name', 'Listed Contact', 'Contact Person') || text('h2'),
    name: value('Company Name') || clean(value('First Name') + ' ' + value('Last Name')) || text('h2'),
    phone: value('Phone - Main', 'Phone - Work', 'Phone') || text('#lead-popup-phone-number'),
    email: value('Email') || text('.led-usr-email'),
    dob: value('Date of Birth', 'DOB', 'Birth Date', "1st Driver's DOB")
      || clean(popupData?.lead_field_data?.DOB || popupData?.lead_field_data?.driver_1_dob),
    street: value('Street Address', 'Address 1', 'Address') || address.street,
    city: value('City') || address.city, state: value('State') || address.state,
    zip: value('Zip', 'Zip Code', 'Postal Code') || address.zip,
    vehicles: value('Vehicles', 'Vehicle', 'Make/Model of Vehicles') || ['1st', '2nd', '3rd', '4th'].map(order =>
      ['Year', 'Make', 'Model'].map(part => vehiclePart(order, part)).filter(Boolean).join(' ')
    ).filter(Boolean).join(', '),
    spouse: value('Spouse Name', 'Spouse'),
    carrier: value('Current Carrier', 'Current Insurer')
      || clean(popupData?.lead_field_data?.Current_Insurance_Carrier || popupData?.lead_field_data?.Carrier),
    lead: value('Lead Type'), lob: value('Line of Business'), owns: value('Home Ownership'),
    vendor: value('Vendor') || readVendor(root),
    agency: value('Agency') || readAgency(root)
  };
  lead.phone = String(lead.phone || '').replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
  const recordId = value('ID') || clean(root.querySelector('webhook-trigger[ui="lead_popup"]')?.getAttribute('lead-id')) || clean(popupData?.popleadId);
  lead.key = /^\d+$/.test(recordId) ? 'id:' + recordId : lead.phone ? 'phone:' + lead.phone : lead.email ? 'email:' + lead.email.toLowerCase() : lead.name ? 'name:' + lead.name.toLowerCase() : '';
  return lead.key ? lead : null;
}

function readField(root, names) {
  const normalize = value => clean(value).replace(/^enter\s+/i, '').replace(/\s*:\s*$/, '').toLowerCase();
  const fields = Array.from(root.querySelectorAll('input, textarea, select')).filter(visible);
  const labels = Array.from(root.querySelectorAll('label'));
  for (const name of names) {
    const wanted = normalize(name);
    for (const field of fields) {
      const label = labels.find(item => (item.htmlFor && item.htmlFor === field.id) || item.contains(field));
      const group = field.closest('.input-group, [as-sortable-item-handle]');
      const groupLabel = group && root.contains(group) ? group.querySelector('label') : null;
      if (![field.getAttribute('placeholder'), field.getAttribute('aria-label'), label?.textContent, groupLabel?.textContent].some(text => normalize(text) === wanted)) continue;
      const result = clean(field.tagName === 'SELECT' ? field.selectedOptions[0]?.textContent : field.value);
      if (result) return result;
    }
  }
  return '';
}

function readVendor(root) {
  for (const group of root.querySelectorAll('.dropdown-button-wrapper')) {
    if (clean(group.querySelector('.dropdown-label')?.textContent).toLowerCase() === 'vendor') {
      const text = clean(group.querySelector('.dropdown-text')?.textContent);
      return text === 'Select Option' ? '' : text;
    }
  }
  // The legacy popup renders Vendor as adjacent columns instead of an input.
  for (const row of root.querySelectorAll('.row')) {
    if (!visible(row)) continue;
    const label = Array.from(row.children).find(el => clean(el.textContent).toLowerCase() === 'vendor:');
    if (label) return clean(label.nextElementSibling?.textContent);
  }
  return '';
}

function readAgency(root) {
  const names = Array.from(root.querySelectorAll('[ng-repeat="tag in lead.lead_tags"]'))
    .map(el => clean(el.textContent)).filter(name => /\s+Agency$/i.test(name));
  if (names.length) return names.length === 1 ? names[0].split(/\s+/)[0] : '';
  // Some sources omit agency tags. Only recognize the known owner names,
  // delimited in the vendor label; do not guess an owner from arbitrary text.
  const vendor = readField(root, ['Vendor']) || readVendor(root);
  const owners = [
    ['Carlos', /(?:^|[\s_-])Carlos(?:Perez)?(?=$|[\s_-])/i],
    ['Ulises', /(?:^|[\s_-])Ulises(?:Gomez)?(?=$|[\s_-])/i],
    ['Stefanie', /(?:^|[\s_-])(?:StefanieP?|Stephanie\s+Pinheiro)(?=$|[\s_-])/i]
  ].filter(([, pattern]) => pattern.test(vendor));
  return owners.length === 1 ? owners[0][0] : '';
}

function parsePopupAddress(value) {
  // The visible popup formats street[, unit], city, state, ZIP with commas.
  // Do not split an unstructured address by guessing where a multiword city starts.
  const raw = clean(value);
  const match = raw.match(/^(.+),\s*([^,]+),\s*([a-z]{2})\s*,?\s*(\d{5}(?:-\d{4})?)$/i)
    || raw.match(/^(.+),\s*([^,]+?)\s+([a-z]{2})\s+(\d{5}(?:-\d{4})?)(?:\s*,\s*)*(?:\3\s*,?\s*)?$/i);
  return match ? {street:clean(match[1]), city:clean(match[2]), state:match[3], zip:match[4]} : {};
}

})();

